INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 21, 'theory', 'Quiz: I/O, buses, and disks');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 0, 'What is memory-mapped I/O (MMIO)?', '["Copying files into memory", "Device registers have addresses in the address space and are accessed with ordinary read and write instructions", "A device attached to the cache", "An interrupt from memory"]', 1, 'A write to such an address is a command to the device, not a change to RAM.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 1, 'When is polling better than interrupts?', '["When events are rare", "When events come very often — the cost of each interrupt outweighs polling", "Never", "Only for a mouse"]', 1, 'That''s why network drivers under high load switch to polling in batches (NAPI, DPDK).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 2, 'What does DMA give you?', '["Speeds up the processor", "The controller itself copies data between the device and memory while the processor does other things", "Encrypts data", "Enlarges the cache"]', 1, 'The processor only has to set the address, size, and direction; when it finishes, a single interrupt arrives.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 3, 'What does the time of a random access to an HDD consist of?', '["Only data transfer", "Seek time, waiting for the right sector (half a revolution on average), and transfer", "Bus delay", "Kernel response time"]', 1, 'At 7200 rpm: ~8 ms seek + ~4.2 ms rotation — about 12 ms per access.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 21, 4, 'How does RAID with parity recover the data of a failed disk?', '["Takes a copy from the mirror", "The XOR of all remaining blocks (including the parity block) gives the lost block", "Reads from the cache", "Overwrites with zeros"]', 1, 'x XOR x = 0, so the XOR of the surviving blocks equals the lost one.');
